{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C18"],
      "claim": "Pamiparib, the closest structural analogue with a fused fluorinated lactam core, shows high oral bioavailability with near-complete absorption in humans, supporting a high F prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "CP-409,092, which shares the methylaminomethylphenyl motif, showed 69% relative oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Vonoprazan, containing a methylaminomethyl group and fluorophenyl, had an estimated human oral bioavailability of 36%, still above the 20% threshold, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Milrinone, a small heteroaromatic drug, had 92% mean absolute oral bioavailability in healthy men, supporting high F for small heteroaromatic lactam-type drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Safinamide had 95% absolute oral bioavailability in humans, supporting high F for orally absorbed basic drugs with aromatic and amine functionality.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Mizolastine had 64.7% mean oral bioavailability in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Sunitinib, a fluorinated oxindole-pyrrole drug, had about 50% absolute oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "A water-soluble non-metabolized TC had ~10% oral bioavailability, the only low result; its very slow absorption profile is not representative of the query, so it is contradictory but low-weight.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is predicted to have high oral bioavailability (F >= 20%). The closest structural analogue (pamiparib) shows near-complete absorption, and the majority of transferable human bioavailability data for related heteroaromatic/lactam drugs are 36-95%, all above threshold. The single low-bioavailability analogue is a poorly absorbed water-soluble compound with low structural transferability.",
  "evidence_gaps": [
    "No direct experimental bioavailability data exist for the query molecule.",
    "All retrieved analogues have low Morgan similarity (<0.28), limiting structural transferability.",
    "No human PK, solubility, permeability, or first-pass metabolism data are available for the query.",
    "The relevance of the single low-bioavailability analogue is uncertain because it is described as water-soluble and very slowly absorbed, unlike the query's more lipophilic fused lactam structure."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

